/**
 * Sorts an array of integers in ascending order using the Bubble Sort algorithm.
 * 
 * The algorithm works by repeatedly stepping through the list, comparing adjacent
 * elements and swapping them if they are in the wrong order. This process is repeated
 * until no swaps are needed, indicating the list is sorted. The largest unsorted
 * element "bubbles up" to its correct position after each full pass.
 * 
 * Time Complexity:
 *   - Worst/Average case: O(n^2) comparisons and swaps.
 *   - Best case (already sorted): O(n) with early termination.
 * Space Complexity: O(1) (in-place sorting).
 * 
 * @param {number[]} arr - The array of integers to sort. Must have at most 100 elements,
 *                         and each element must be an integer between -10000 and 10000.
 * @returns {number[]} The sorted array (in ascending order).
 * @throws {TypeError} If input is not an array or contains non‑integer values.
 * @throws {RangeError} If array length exceeds 100 or any element is out of range.
 */
function bubbleSort(arr) {
    // Input validation
    if (!Array.isArray(arr)) {
        throw new TypeError('Input must be an array');
    }

    if (arr.length > 100) {
        throw new RangeError('Array length must not exceed 100');
    }

    for (let i = 0; i < arr.length; i++) {
        if (!Number.isInteger(arr[i])) {
            throw new TypeError('Array elements must be integers');
        }
        if (arr[i] < -10000 || arr[i] > 10000) {
            throw new RangeError('Array elements must be between -10000 and 10000');
        }
    }

    // Bubble sort implementation
    const n = arr.length;
    // Outer loop: perform up to n-1 passes
    for (let i = 0; i < n - 1; i++) {
        let swapped = false;
        // Inner loop: compare adjacent elements; after i passes, the last i elements are sorted
        for (let j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // Swap the two elements
                const temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                swapped = true;
            }
        }
        // If no swaps occurred, the array is already sorted → early exit
        if (!swapped) {
            break;
        }
    }

    return arr; // The array is sorted in place, also returned for convenience
}

// Example usage (commented out):
// const unsorted = [5, 2, 8, -1, 0];
// bubbleSort(unsorted); // unsorted becomes [-1, 0, 2, 5, 8]
