        const detailType = document.getElementById('detail-type');
        const detailName = document.getElementById('detail-name');
        const detailYear = document.getElementById('detail-approx');
        const detailDesc = document.getElementById('detail-desc');

        // --- INITIALIZATION ---
        function init() {
            // UI Init
            document.getElementById('current-time').textContent = new Date().toISOString().split('T')[0];
            renderCards();

            // Entrance Animations
            setTimeout(() => {
                gsap.to('.reveal-text', { opacity: 1, y: 0, duration: 1, ease: "power3.out" });
                gsap.to('.reveal-sub', { opacity: 1, y: 0, duration: 1, delay: 0.2, ease: "power3.out" });
                gsap.to('.reveal-search', { opacity: 1, y: 0, duration: 1, delay: 0.4, ease: "power3.out" });
                gsap.to('.reveal-grid', { opacity: 1, y: 0, duration: 1, delay: 0.6, ease: "power3.out" });
            }, 100);

            // Three.js Init
            initThreeJS();
            animate();
        }

        // --- THREE.JS SETUP ---
        function initThreeJS() {
            const container = document.getElementById('canvas-container');

            scene = new THREE.Scene();
            // Fog for depth
            scene.fog = new THREE.FogExp2(0x0c0a09, 0.02);

            camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 0, 15);

            renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2)); // Perf optimization
            renderer.toneMapping = THREE.ACESFilmicToneMapping;
            renderer.outputEncoding = THREE.sRGBEncoding;
            container.appendChild(renderer.domElement);

            // Lights
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
            scene.add(ambientLight);

            const spotLight = new THREE.SpotLight(0xffaa00, 2);
            spotLight.position.set(10, 20, 10);
            spotLight.angle = Math.PI / 4;
            spotLight.penumbra = 0.5;
            spotLight.castShadow = true;
            scene.add(spotLight);

            const fillLight = new THREE.PointLight(0x44aaff, 1);
            fillLight.position.set(-10, -10, 5);
            scene.add(fillLight);

            // 1. Create Main Artifact (Ghost Mode initially)
            createBackgroundArtifact();

            // 2. Create Particles
            createParticles();

            // Handle Resize
            window.addEventListener('resize', onWindowResize, false);

            // Interaction (Mouse Move for Parallax)
            document.addEventListener('mousemove', onMouseMove, false);
        }

        function createBackgroundArtifact() {
            // Initially create a "mystery" abstract shape
            const geometry = new THREE.IcosahedronGeometry(3, 1);
            const material = new THREE.MeshPhysicalMaterial({
                color: 0x333333,
                wireframe: true,
                transparent: true,
                opacity: 0.1,
                roughness: 0.1,
                metalness: 1.0,
                clearcoat: 1.0
            });

            mainArtifact = new THREE.Mesh(geometry, material);
            scene.add(mainArtifact);
        }

        function createParticles() {
            const particlesGeometry = new THREE.BufferGeometry();
            const particlesCount = 700;

            const posArray = new Float32Array(particlesCount * 3);

            for(let i = 0; i < particlesCount * 3; i++) {
                posArray[i] = (Math.random() - 0.5) * 40; // Spread
            }

            particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));

            const material = new THREE.PointsMaterial({
                size: 0.05,
                color: 0x444444,
                transparent: true,
                opacity: 0.4
            });

            backgroundParticles = new THREE.Points(particlesGeometry, material);
            scene.add(backgroundParticles);
        }

        function onMouseMove(event) {
            if (!mainArtifact) return;

            // Subtle parallax based on mouse
            const mouseX = (event.clientX / window.innerWidth) * 2 - 1;
            const mouseY = -(event.clientY / window.innerHeight) * 2 + 1;

            if(!isDetailMode) {
                gsap.to(mainArtifact.rotation, {
                    x: mouseY * 0.2,
                    y: mouseX * 0.2 + Date.now() * 0.00005, // constant slow rotation
                    duration: 1
                });
                gsap.to(backgroundParticles.rotation, {
                    x: mouseY * 0.05,
                    y: mouseX * 0.05,
                    duration: 2
                });
            }
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function animate() {
            requestAnimationFrame(animate);

            const time = Date.now() * 0.001;

            // Ambient animations
            if (backgroundParticles) {
                backgroundParticles.rotation.y += 0.0005;
            }

            if (mainArtifact && !isDetailMode) {
                mainArtifact.rotation.y += 0.002;
                // Hover effect
                mainArtifact.position.y = Math.sin(time) * 0.2;
            }

            renderer.render(scene, camera);
        }

        // --- UI LOGIC ---

        function renderCards() {
            artifactGrid.innerHTML = '';
            artifacts.forEach((item, index) => {
                const card = document.createElement('div');
                card.className = 'artifact-card bg-stone-900/80 p-6 rounded cursor-pointer backdrop-blur-sm relative overflow-hidden group';
                card.onclick = () => openArtifact(index);

                card.innerHTML = `
                    <div class="absolute top-0 right-0 p-2 opacity-50 group-hover:opacity-100 transition-opacity">
