        function performSearch() {
            const query = document.getElementById('search-input').value.toLowerCase();
            // Simple visual search feedback
            const cards = document.querySelectorAll('.artifact-card');
            let found = false;

            cards.forEach(card => {
                const text = card.innerText.toLowerCase();
                if(text.includes(query)) {
                    card.style.opacity = '1';
                    card.style.display = 'block';
                    found = true;
                } else {
                    card.style.opacity = '0.3';
                }
            });

            if(!found) alert("No artifacts matching query found.");
        }

        function openArtifact(index) {
            const item = artifacts[index];
            isDetailMode = true;

            // 1. Populate Data
            detailId.innerText = item.id;
            detailType.innerText = item.type;
            detailName.innerText = item.name;
            detailYear.innerText = item.year;
            detailDesc.innerText = item.desc;

            // 2. Camera Transition to 3D Object Area
            // Hide Home UI
            gsap.to(homeView, { 
                opacity: 0, 
                duration: 0.5, 
                onComplete: () => {
                    homeView.style.display = 'none';
                    artifactView.style.pointerEvents = 'auto'; // Enable click-through blocking

                    // Show Detail Panel
                    artifactView.classList.remove('hidden-panel');
                    gsap.to(artifactView, { opacity: 1, duration: 0.5 });
                    gsap.to(detailPanel, { x: '0%', duration: 0.8, ease: "power3.inOut" });
                }
            });

            // 3. Reconstruct 3D Model based on data
            replaceArtifactModel(item);

            // 4. Move Camera
            // Move camera closer and slightly to the left to leave room for panel
            gsap.to(camera.position, {
                x: -4,
                y: 1,
                z: 6,
                duration: 1.5,
                ease: "power2.inOut"
            });

            gsap.to(camera, {
                fov: 50, // Zoom in slightly
                duration: 1.5,
                onUpdate: () => camera.updateProjectionMatrix(),
                ease: "power2.inOut"
            });

            // Add Orbit Controls for detail view
            const controls = new THREE.OrbitControls(camera, renderer.domElement);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.enableZoom = true;
            controls.autoRotate = false;
            // Hook controls into loop (simple version: we just use the standard loop rotation stopped, manual controls active)
            // Note: To properly integrate OrbitControls in this simplified structure, we'd usually pass it to animate loop.
            // For this demo, let's rely on the mouse move parallax or just let it stay static/rotating slowly.
            // We will enable rotation via mouse in the animate loop based on interaction state.

            window.customControls = controls;
        }

        function replaceArtifactModel(item) {
            if(mainArtifact) {
                let old = mainArtifact;
                // Animate out
