                    duration: 0.5,
                    onComplete: () => scene.remove(old)
                });
            }

            let geometry;
            // Simple Geometry Switcher based on type for demo
            if(item.shape === 'octahedron') geometry = new THREE.OctahedronGeometry(2.5, 1); // Stylized
            else if(item.shape === 'sphere') geometry = new THREE.SphereGeometry(2.2, 32, 32); 
            else geometry = new THREE.ConeGeometry(2.5, 4, 32);

            // High quality Material
            const material = new THREE.MeshPhysicalMaterial({
                color: item.color,
                metalness: 0.2, // Stone vs Metal
                roughness: 0.1,
                clearcoat: 0.8,
                clearcoatRoughness: 0.1,
                envMapIntensity: 1,
                flatShading: item.shape === 'octahedron' // Low poly look for stone
            });

            mainArtifact = new THREE.Mesh(geometry, material);

            // Add wireframe overlay for "Scanning" effect
            const wiregeo = new THREE.WireframeGeometry(geometry);
            const wiremat = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.1 });
            const wireframe = new THREE.LineSegments(wiregeo, wiremat);
            mainArtifact.add(wireframe);

            mainArtifact.rotation.set(0, Math.PI/4, 0);

            // Animate in
            mainArtifact.scale.set(0,0,0);
            scene.add(mainArtifact);

            gsap.to(mainArtifact.scale, {
                x: 1, y: 1, z: 1,
                duration: 1,
                ease: "elastic.out(1, 0.5)",
                delay: 0.5
            });
        }

        function returnToHome() {
            isDetailMode = false;

            // UI Transition
            gsap.to(detailPanel, { x: '100%', duration: 0.5, ease: "power2.in" });
            gsap.to(artifactView, { opacity: 0, duration: 0.5 });

            setTimeout(() => {
                artifactView.classList.add('hidden-panel');
                artifactView.style.opacity = ''; // reset
                artifactView.style.pointerEvents = 'none';

                homeView.style.display = 'block';
                gsap.to(homeView, { opacity: 1, duration: 0.5 });
            }, 500);

            // Camera Reset
            gsap.to(camera.position, {
                x: 0, y: 0, z: 15,
                duration: 1.2,
                ease: "power2.inOut"
            });

            gsap.to(camera, {
                fov: 45,
                duration: 1.2,
                onUpdate: () => camera.updateProjectionMatrix()
            });

            // Reset Model to Ghost
            if(mainArtifact) {
                let old = mainArtifact;
                gsap.to(old.scale, {
                    x: 0, y: 0, z: 0,
                    duration: 0.5,
                    onComplete: () => {
                        scene.remove(old);
                        createBackgroundArtifact(); // Re-add ghost
                    }
                });
            }
        }

        // Start
        init();

    </script>
